props.bindScript:
var total = data.length;
var done = 0;
for (var i = 0; i < data.length; i++) {
  if (data[i]['是否完成']) { done++; }
}
var undone = total - done;
var fmt = function (n) { return n.toLocaleString('en-US'); };
var rate = total > 0 ? ((done / total) * 100).toFixed(1) + '%' : '0.0%';
var unrate = total > 0 ? ((undone / total) * 100).toFixed(1) + '%' : '0.0%';
return { value_map: { '录入': fmt(total), '完成人数': fmt(done), '未完成人数': fmt(undone), '完成率': rate, '未完成率': unrate } };

var count = 0;
for (var i = 0; i < data.length; i++) {
  if (data[i]['性别'] === '男') count++;
}
return {value: count + '人'};

var count = 0;
for (var i = 0; i < data.length; i++) {
  var r = data[i];
  if (r && r['性别'] === '男' && r['是否完成'] === true) count++;
}
return {value: count};

var count = 0;
if (Array.isArray(data)) {
  for (var i = 0; i < data.length; i++) {
    var r = data[i];
    if (r && r["性别"] === "女" && r["是否完成"] === true) count++;
  }
}
return {value: count + " 人"};

var rows = (data || []).filter(function (r) {
  return r && r['报告内容'] && r['报告内容']['指标分数'] && r['报告内容']['指标分数']['预警等级'] === '一级预警';
}).slice(0, 10);
var gender = [], pressure = [], harm = [], sad = [], dep = [], anx = [];
rows.forEach(function (r) {
  var s = r['报告内容']['指标分数'];
  gender.push(String(r['性别'] == null ? '-' : r['性别']));
  pressure.push(String(s['学习压力'] == null ? '-' : s['学习压力']));
  harm.push(String(s['自我伤害倾向'] == null ? '-' : s['自我伤害倾向']));
  var d = Number(s['抑郁']) || 0, a = Number(s['焦虑']) || 0;
  sad.push(((d + a) / 2).toFixed(1));
  dep.push(String(s['抑郁'] == null ? '-' : s['抑郁']));
  anx.push(String(s['焦虑'] == null ? '-' : s['焦虑']));
});
return { value_map: { '性别': gender, '学习压力': pressure, '自我伤害倾向': harm, '难过': sad, '抑郁': dep, '焦虑': anx } };

var names=['学习压力','情绪不稳定'];
var avg=[],focus=[],key=[];
for(var i=0;i<names.length;i++){
  var vals=[];
  for(var j=0;j<data.length;j++){
    var r=data[j];
    if(!r['是否完成']||!r['报告内容']||!r['报告内容']['指标分数'])continue;
    var v=r['报告内容']['指标分数'][names[i]];
    if(typeof v==='number'&&v>=1&&v<=5)vals.push(v);
  }
  var n=vals.length;
  var sum=0,c3=0,c4=0;
  for(var k=0;k<n;k++){sum+=vals[k];if(vals[k]>=3)c3++;if(vals[k]>=4)c4++;}
  avg.push(n?(sum/n).toFixed(1):'-');
  focus.push(String(c3));
  key.push(String(c4));
}
return {value_map:{'指标':names,'平均分':avg,'关注人数':focus,'重点关注人数 ':key}};
